/**
 * `repr()` of a Python `str`.
 *
 * Both `int()`'s ValueError text and argparse's "invalid int value" text embed
 * the offending argument through `%r`, so the escaping rules have to match
 * CPython exactly: single quotes unless that would need escaping, short escapes
 * for backslash / quote / newline / carriage return / tab, and `\xXX`, `\uXXXX`
 * or `\UXXXXXXXX` for anything `str.isprintable()` rejects.
 */

import { isPythonPrintable } from './unicode.mjs';

const SHORT_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

function hexEscape(prefix, codePoint, width) {
  return `\\${prefix}${codePoint.toString(16).padStart(width, '0')}`;
}

export function pythonRepr(text) {
  const quote = text.includes("'") && !text.includes('"') ? '"' : "'";
  let body = '';
  for (const character of text) {
    const short = SHORT_ESCAPES.get(character);
    if (short !== undefined) {
      body += short;
      continue;
    }
    if (character === quote) {
      body += `\\${quote}`;
      continue;
    }
    const codePoint = character.codePointAt(0);
    if (isPythonPrintable(codePoint)) body += character;
    else if (codePoint < 0x100) body += hexEscape('x', codePoint, 2);
    else if (codePoint < 0x10000) body += hexEscape('u', codePoint, 4);
    else body += hexEscape('U', codePoint, 8);
  }
  return quote + body + quote;
}
