const EXTRA_SPACE_CODE_POINTS = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x1c, 0x1d, 0x1e, 0x1f, 0x20, 0x85,
]);

/** Zs plus LINE SEPARATOR (U+2028) and PARAGRAPH SEPARATOR (U+2029). */
const SPACE_SEPARATOR = new RegExp('^[\\p{Zs}\\u2028\\u2029]$', 'u');

/** Categories for which `str.isprintable()` is false (ASCII space is the one exception). */
const NON_PRINTABLE = buildNonPrintableMatcher();

function buildNonPrintableMatcher() {
