 * Exception objects shaped like the CPython ones this script can raise.
 *
 * Only the pieces the traceback printer needs are modelled: the exception class
 * name as Python spells it, and the `str()` of the exception instance.
 */

export class PythonError extends Error {
  constructor(typeName, message) {
    super(`${typeName}: ${message}`);
    this.typeName = typeName;
    this.pythonMessage = message;
  }
}

export class PythonValueError extends PythonError {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PythonIndexError extends PythonError {
  constructor(message) {
