/**
 * Synchronous stdio writers.
 *
 * `process.stdout.write` is asynchronous when stdout is a pipe, so anything
 * written just before `process.exit()` can be lost.  Every diagnostic path here
 * ends in an exit, so all of them go through `writeSync`.
 */

import { writeSync } from 'node:fs';

const STDOUT_FD = 1;
const STDERR_FD = 2;

function write(fileDescriptor, text) {
  const buffer = Buffer.from(text, 'utf8');
  let written = 0;
  while (written < buffer.length) {
    try {
      written += writeSync(fileDescriptor, buffer, written);
    } catch (error) {
      if (error.code === 'EAGAIN') continue;
      if (error.code === 'EPIPE') return;
      throw error;
    }
  }
}

export function writeStdout(text) {
  write(STDOUT_FD, text);
}

export function writeStderr(text) {
  write(STDERR_FD, text);
}

